  if(app==='calculator')return '<div class="calc"><output class="calc-out">'+esc((calc||'0').replace(/\*/g,'×').replace(/\//g,'÷').replace(/-/g,'−'))+'</output><div class="calc-keys">'+[['AC','fn'],['(','fn'],[')','fn'],['/','op'],['7'],['8'],['9'],['*','op'],['4'],['5'],['6'],['-','op'],['1'],['2'],['3'],['+','op'],['⌫','fn'],['0'],['.'],['=','op']].map(([k,c=''])=>'<button class="ck '+c+'" data-calc="'+k+'">'+({'/':'÷','*':'×','-':'−'}[k]||k)+'</button>').join('')+'</div></div>';
