  if(app==='factions'||app==='jobs'){const jobs=app==='jobs';return nav(jobs?'Meslekler':'Birlik',{back:'Ana Ekran'})+'<div class="hero '+(jobs?'t-orange':'t-purple')+'">'+svg(jobs?'briefcase':'people')+'<p>'+(jobs?'Legal ve illegal meslekleri incele, başlangıç noktasını haritada bul.':'Birlik üyeliğini, duyuruları ve kasayı yönet.')+'</p></div><button class="btn" data-method="'+app+'">Paneli Aç</button>';}
