  if(app==='exchange')return nav('Borsa',{back:'Ana Ekran'})+'<p class="foot top">Yalnız oyun içi şirketler ve oyun parası · fiyatlar 5 dakikada bir değişir.</p><div class="stocks">'+(appData?.quotes||[]).map(v=>{const owned=appData.holdings.find(h=>h.symbol===v.symbol)?.qty||0,ch=Number(v.change??v.change_pct??0);return '<article class="stock"><div class="s-main"><span><strong>'+esc(v.symbol)+'</strong><small>'+esc(v.name)+'</small></span><span class="s-r"><b>$'+v.price+'</b><i class="chg '+(ch<0?'down':'up')+'">'+(ch?(ch>0?'+':'')+ch+'%':owned+' adet')+'</i></span></div><div class="s-trade"><input type="number" data-shares="'+v.symbol+'" value="1" min="1" max="100" aria-label="Adet"><button data-trade="buy" data-symbol="'+v.symbol+'">Al</button><button data-trade="sell" data-symbol="'+v.symbol+'" class="sell">Sat</button></div></article>';}).join('')+'</div>';
